#include <Snooker/Rules/FrameSave.h>
#include <fstream>
#include <iterator>
#include <iostream>
#define CHECK(x) do{if(!(x)){std::cerr<<"FAIL frame save "<<__LINE__<<": "<<#x<<"; "<<error<<'\n';return 1;}}while(false)
std::string Read(const char* p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}void Write(const char* p,const std::string& t){std::ofstream f(p,std::ios::binary);f<<t;}
int main(int argc,char** argv){using namespace Snooker;std::string error;if(argc>=2&&std::string(argv[1])=="--make"){CHECK(argc==6);PhysicsBundle b;PhysicsSnapshot p;ShotInput input;CHECK(PhysicsBundle::Deserialize(Read(argv[2]),b,&error));CHECK(PhysicsSnapshot::Deserialize(Read(argv[3]),p,&error));CHECK(ShotInput::Deserialize(Read(argv[4]),input,&error));FrameSave save;save.Parameters=b;save.Physics=p;save.Match.Scores={42,17};save.Match.CurrentPlayer=1;BallDefinition d;d.Id=1;d.Type=EBallType::Cue;d.InitialPositionMeters=p.Balls[0].PositionMeters;d.RadiusMeters=p.Balls[0].RadiusMeters;d.MassKg=p.Balls[0].MassKg;d.MaterialProfileId=p.Balls[0].MaterialProfileId;save.Definitions={d};CHECK(save.IsValid(&error));Write(argv[5],save.Serialize());return 0;}CHECK(argc==2);FrameSave save;CHECK(FrameSave::Deserialize(Read(argv[1]),save,&error));CHECK(save.Shots.size()==2&&save.Match.Scores[0]==42&&save.Match.Scores[1]==17&&save.Match.CurrentPlayer==1);const auto text=save.Serialize();FrameSave loaded;CHECK(FrameSave::Deserialize(text,loaded,&error));CHECK(loaded.Serialize()==text);CHECK(!FrameSave::Deserialize(text+"tail",loaded,&error));CHECK(loaded.Serialize()==text);auto direct=save;direct.Shots.clear();direct.Physics=save.Shots.front().Initial;FrameSave one,two;CHECK(ContinueFrame(direct,save.Shots[0].Input,one,nullptr,&error));CHECK(ContinueFrame(one,save.Shots[1].Input,two,nullptr,&error));CHECK(two.Serialize()==save.Serialize());std::cout<<"PASS frame save process continuation, history, match and transactional parse\n";}
